actions.script:
const out = ec.service.sync().name('org.moqui.call.SmsRoomServices.find#TextMembers').parameter('chatRoomId', chatRoomId || '').call() || {}
ec.web.sendJsonResponse(ec.message.hasError() ? {reasonCode: out.reasonCode || null} : {memberList: out.memberList || [], canAdd: !!out.canAdd,
    addRefusal: out.addRefusal || null, maxMembers: out.maxMembers ?? null})

const out = ec.service.sync().name('org.moqui.call.SmsRoomServices.add#TextMember').parameters({chatRoomId: chatRoomId || '', phoneNumber: phoneNumber || '',
    memberName: memberName || null, ourNumber: ourNumber || null, consent: String(consent) === 'true' ? 'Y' : 'N'}).call() || {}
ec.web.sendJsonResponse(ec.message.hasError() ? {reasonCode: out.reasonCode || null} : {chatActorId: out.chatActorId, ourNumber: out.ourNumber,
    warning: out.warning || null, welcomeSent: !!out.welcomeSent})

const out = ec.service.sync().name('org.moqui.call.SmsRoomServices.rename#TextMember').parameters({chatRoomId: chatRoomId || '', chatActorId: chatActorId || '',
    memberName: memberName || null}).call() || {}
ec.web.sendJsonResponse(ec.message.hasError() ? {reasonCode: out.reasonCode || null} : {memberName: out.memberName || null})
